items.example:
e(Ui.Field, { orientation = "horizontal" }, {
	Content = e(Ui.FieldContent, { layoutOrder = 1 }, {
		Label = e(Ui.FieldLabel, { text = "Music" }),
		Hint = e(Ui.FieldDescription, { text = "Background soundtrack" }),
	}),
	Toggle = e(Ui.Switch, { checked = musicOn, onCheckedChanged = setMusicOn, layoutOrder = 2 }),
})

e(Ui.ProgressBar, {
	value = xp,
	maximum = 100,
	-- indeterminate = true, -- animated loading state
})

e(Ui.Switch, {
	checked = musicOn,
	onCheckedChanged = setMusicOn,
})

e(Ui.HoldButton, {
	text = "Hold to sell",
	variant = "destructive",
	duration = 1.2,
	onCompleted = sellItem,
})

e(Ui.RadialProgress, {
	value = cooldownLeft,
	maximum = 10,
}, {
	Label = e(Ui.Text, { text = tostring(cooldownLeft), variant = "caption" }),
})

e(Ui.FieldGroup, nil, {
	Music = e(Ui.Field, { layoutOrder = 1 }, musicRow),
	Sfx = e(Ui.Field, { layoutOrder = 2 }, sfxRow),
})

e(Ui.TextField, {
	placeholder = "Enter a code",
	onSubmitted = function(text)
		redeem(text)
	end,
})

e(Ui.Container, {
	variant = "raised", -- surface | raised | muted | accent | destructive
	size = UDim2.fromOffset(320, 0), -- height grows with content
	position = UDim2.fromOffset(24, 24),
	contentPadding = UDim.new(0, 16),
}, {
	Title = e(Ui.Text, { text = "Quests", variant = "heading", layoutOrder = 1 }),
	Body = e(Ui.Text, { text = "Find the lost relic.", layoutOrder = 2 }),
})

e(Ui.Dialog, {
	open = isOpen,
	title = "Leave the match?",
	description = "Your progress will be saved.",
	onOpenChange = setOpen,
	footer = {
		Confirm = e(Ui.Button, { text = "Leave", variant = "destructive", onActivated = leave }),
	},
})

e(Ui.Checkbox, {
	checked = accepted,
	onCheckedChanged = setAccepted,
})

e(Ui.RadioGroup, {
	value = difficulty,
	onValueChanged = setDifficulty,
}, {
	Easy = e(Ui.RadioGroupItem, { value = "easy", layoutOrder = 1 }),
	Hard = e(Ui.RadioGroupItem, { value = "hard", layoutOrder = 2 }),
})

e(Ui.Button, {
	text = "Play",
	variant = "primary", -- secondary | outline | ghost | destructive
	onActivated = function()
		print("clicked")
	end,
})

e(Ui.Text, {
	text = "Welcome back",
	variant = "heading", -- display | heading | body | subtext | caption
	tone = "default", -- muted | success | warning | danger
})

e(Ui.IconButton, {
	icon = "rbxassetid://0000000", -- your icon asset
	label = "Settings",
	shape = "circle",
	onActivated = openSettings,
})
